export function PageTransition({
  style = "{{style}}",
  duration = {{duration}},
  loop = {{loop}},
  accent = "{{accent}}",
}) {
  const cls = loop ? "cycle" : "";
  return (
    <div style={{ position: "relative", width: "100%", maxWidth: 320, height: 100, background: "#FAF7F2", border: "1px solid #24143022", borderRadius: 12, overflow: "hidden", fontFamily: "system-ui, sans-serif", fontSize: 13, color: "#241430aa" }}>
      <div className={`page-a ${cls}`} style={{ position: "absolute", inset: 0, display: "grid", placeItems: "center", fontWeight: 700, color: "#241430", background: accent }}>Page A</div>
      <div className={`page-b ${cls}`} style={{ position: "absolute", inset: 0, display: "grid", placeItems: "center", fontWeight: 700, color: "#241430", background: "#FAF7F2", border: "2px dashed #24143033", opacity: 0 }}>Page B</div>
      <p style={{ position: "absolute", bottom: -26, left: 0 }}>{style} transition &middot; {duration}ms between routes</p>
      <style>{`
        @media (prefers-reduced-motion: no-preference) {
          [data-style="fade"] .page-a.cycle, .fade-a { animation: mot-pgt-fade-out ${duration}ms ease-in-out infinite; }
          .page-a.cycle { animation: ${style === "fade" ? "mot-pgt-fade-out" : style === "slide" ? "mot-pgt-slide-out" : "mot-pgt-scale-out"} ${duration}ms ease-in-out infinite; }
          .page-b.cycle { animation: ${style === "fade" ? "mot-pgt-fade-in" : style === "slide" ? "mot-pgt-slide-in" : "mot-pgt-scale-in"} ${duration}ms ease-in-out infinite; }
          @keyframes mot-pgt-fade-out { 0%,45% { opacity: 1; } 50%,100% { opacity: 0; } }
          @keyframes mot-pgt-fade-in { 0%,45% { opacity: 0; } 50%,95% { opacity: 1; } 100% { opacity: 0; } }
          @keyframes mot-pgt-slide-out { 0%,45% { transform: translateX(0); } 50%,100% { transform: translateX(-100%); } }
          @keyframes mot-pgt-slide-in { 0%,45% { transform: translateX(100%); opacity: 1; } 50%,95% { transform: translateX(0); opacity: 1; } 100% { transform: translateX(100%); } }
          @keyframes mot-pgt-scale-out { 0%,45% { opacity: 1; transform: scale(1); } 50%,100% { opacity: 0; transform: scale(1.15); } }
          @keyframes mot-pgt-scale-in { 0%,45% { opacity: 0; transform: scale(.85); } 50%,95% { opacity: 1; transform: scale(1); } 100% { opacity: 0; } }
        }
      `}</style>
    </div>
  );
}
